{"file_text": "from app.api.handlers import handle_user_initials


def test_user_initials_two_words():
    assert handle_user_initials({"id": "1"}) == (200, {"initials": "AL"})


def test_user_initials_other_user():
    assert handle_user_initials({"id": "3"}) == (200, {"initials": "GH"})


def test_user_initials_one_word(monkeypatch):
    monkeypatch.setattr(
        "app.api.handlers.users.get_user",
        lambda user_id: {"id": user_id, "name": "Prince", "email": "prince@example.com"},
    )
    assert handle_user_initials({"id": "1"}) == (200, {"initials": "P"})


def test_user_initials_many_words():
    monkeypatch.setattr(
        "app.api.handlers.users.get_user",
        lambda user_id: {"id": user_id, "name": "Mary Jane Watson", "email": "mj@example.com"},
    )
    assert handle_user_initials({"id": "1"}) == (200, {"initials": "MW"})


def test_user_initials_invalid_missing_id():
    assert handle_user_initials({}) == (400, {"error": "invalid id"})


def test_user_initials_invalid_non_string_id():
    assert handle_user_initials({"id": 1}) == (400, {"error": "invalid id"})


def test_user_initials_invalid_non_digit_id():
    assert handle_user_initials({"id": "abc"}) == (400, {"error": "invalid id"})


def test_user_initials_not_found():
    assert handle_user_initials({"id": "99"}) == (404, {"error": "not found"})
